import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
ORDER_ID = os.getenv("PRODUCTION_ORDER_ID", "replace-with-order-id")
HISTORICAL_REPORT_ID = os.getenv("HISTORICAL_REPORT_ID", "replace-with-report-id")

session = requests.Session()
session.headers.update({"Accept": "application/json"})

def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.status_code == 204 or not response.content:
        return None
    return response.json()

order_status = request("GET", f"/production/orders/{ORDER_ID}/status")
deliveries_response = request("GET", "/deliveries")
deliveries = deliveries_response if isinstance(deliveries_response, list) else (
    deliveries_response.get("deliveries", []) if isinstance(deliveries_response, dict) else []
)

delivery_details = []
for delivery in deliveries:
    delivery_id = delivery.get("id") or delivery.get("deliveryId")
    if delivery_id is not None:
        details = request("GET", f"/deliveries/{delivery_id}")
        delivery_details.append((delivery_id, details))

def is_incomplete(delivery):
    status = str(delivery.get("status", "")).lower().replace("_", "-")
    return status in {"incomplete", "failed", "cancelled", "canceled", "undelivered"}

def is_unnecessary(delivery):
    status = str(delivery.get("status", "")).lower().replace("_", "-")
    return status in {"completed", "delivered", "unnecessary", "duplicate"}

deleted_deliveries = []
for delivery_id, details in delivery_details:
    if is_incomplete(details) or is_unnecessary(details):
        request("DELETE", f"/deliveries/{delivery_id}")
        deleted_deliveries.append({"id": delivery_id, "details": details})

incidents = []
for delivery_id, details in delivery_details:
    if is_incomplete(details):
        incident = request(
            "POST",
            "/incident-report",
            json={
                "summary": f"Incomplete delivery {delivery_id} encountered during production order review",
                "description": (
                    "An incomplete delivery was identified while reviewing deliveries "
                    f"associated with production order {ORDER_ID}. Delivery details: {details}"
                ),
            },
        )
        incidents.append(incident)

mineral_distribution = request("GET", "/mineral-distribution")
yield_parameters = {
    "productionOrderId": ORDER_ID,
    "mineralDistribution": mineral_distribution,
    "incidents": incidents,
    "deletedDeliveries": deleted_deliveries,
}
updated_yield = request("POST", "/yield-calculation", json=yield_parameters)
historical_analytics = request("GET", f"/analytics/{HISTORICAL_REPORT_ID}")

results = {
    "productionOrderStatus": order_status,
    "deliveries": [details for _, details in delivery_details],
    "deletedDeliveries": deleted_deliveries,
    "incidents": incidents,
    "mineralDistribution": mineral_distribution,
    "updatedYieldPrediction": updated_yield,
    "historicalAnalytics": historical_analytics,
}
print(results)

