import requests

BASE_URL = "https://api.socbench.example"

performance_response = requests.get(f"{BASE_URL}/performance")
performance_response.raise_for_status()
performance_data = performance_response.json()

# Identify systems explicitly reported as underperforming or degraded.
underperforming = []
records = performance_data if isinstance(performance_data, list) else performance_data.get(
    "resources", performance_data.get("metrics", [])
)

if isinstance(records, list):
    for record in records:
        if not isinstance(record, dict):
            continue
        status = str(record.get("status", "")).lower()
        performance = str(record.get("performance", record.get("health", ""))).lower()
        if any(term in status or term in performance for term in ("underperform", "degraded")):
            underperforming.append(record)

if underperforming:
    alert_response = requests.post(
        f"{BASE_URL}/alert",
        json={
            "title": "Degraded resource performance detected",
            "description": "Configured resources are exhibiting underperforming or degraded performance levels.",
            "systems": underperforming,
            "performanceMetrics": performance_data,
            "notifyRelevantTeam": True,
        },
    )
