status_response.raise_for_status()
status_data = status_response.json()
components = status_data.get("components", [])

# Identify components that may need attention based on their reported status.
issue_statuses = {"under maintenance", "faulty"}
potential_issues = [
    component
    for component in components
    if str(component.get("status", "")).lower() in issue_statuses
]

# Fetch sensor readings and flag sensors with irregular performance metrics.
sensor_response = requests.get(f"{BASE_URL}/sensors/overview")
sensor_response.raise_for_status()
sensors = sensor_response.json().get("sensors", [])

irregular_sensor_ids = set()
for sensor in sensors:
    readings = [
        reading["value"]
        for reading in sensor.get("readings", [])
        if isinstance(reading.get("value"), (int, float))
    ]
    if str(sensor.get("status", "")).lower() == "faulty":
        irregular_sensor_ids.add(sensor.get("sensorId"))
    elif len(readings) >= 2 and max(readings) != min(readings):
        # Treat changing readings as irregular for anomaly analysis.
        irregular_sensor_ids.add(sensor.get("sensorId"))

# Run anomaly detection for components with issues or irregular sensor metrics.
component_ids = {
    component.get("id")
    for component in potential_issues
    if component.get("id")
}
component_ids.update(
    component.get("id")
    for component in components
    if component.get("id") in irregular_sensor_ids
)

anomaly_result = None
if component_ids:
    anomaly_payload = {
        "componentIds": sorted(component_ids),
        "timePeriod": {
